/// <summary>
/// Subscribed Lookup event to display Customer accounts, name based on the Internal customer
/// </summary>
/// <param name="sender">FormControl type object</param>
/// <param name="e">FormControlEventArgs type object</param>
[FormControlEventHandler(formControlStr(InventTransferOrders, METInventTransferTableExt_InternalCustomer), FormControlEventType::Lookup),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void METInventTransferTableExt_InternalCustomer_OnLookup(FormControl sender, FormControlEventArgs e)
{
    Query                   query;
    SysTableLookup          sysTableLookup      = SysTableLookup::newParameters(tableNum(CustTable), sender);
    QueryBuildDataSource    queryBuildDataSource;

    query               = new Query();
    sysTableLookup      = SysTableLookup::newParameters(tableNum(CustTable), sender);

    sysTableLookup.addLookupField(fieldNum(CustTable, AccountNum));
    sysTableLookup.addLookupMethod(tableMethodStr(CustTable, name));
    sysTableLookup.addLookupField(fieldNum(CustTable, DataAreaId));

    queryBuildDataSource = query.addDataSource(tableNum(CustTable));

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
